const SUBJECT_DIR = path.join(ROOT, "prep/overlays/maikbook2/pharmacology");
const KB_DIR = path.join(ROOT, "kb/reference");
const LESSON_DIR = path.join(ROOT, "prep/lessons/v1");
const MODEL = "muse-wonder (local authoring, no external API)";
const ITEM_META = { prov: "SMD", gen: "hand", set: "maikbook2", d: 2, cog: "application", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against standard peer references" } } } };
let failures = 0, written = 0, kbWritten = 0, kbSkipped = 0;
for (const m of M) {
  const steps = m.steps.map((s) => JSON.parse(JSON.stringify(s)));
  for (const s of steps) {
    const words = s.tx.split(/\s+/).filter(Boolean).length;
    if (words < 40 || words > 90) { console.error("FAIL", m.id, words); failures++; }
  }
  const quiz = m.mcqs.map((q) => q.id);
  const lesson = {
    v: 1, module: m.id, subject: "pharmacology", title: m.title, minutes: 6,
    steps, quiz, src: [], refs: [REF], gen: "AI", run: "books2-pharma4", model: MODEL,
    checks: { shape: true, numbers: true, drugs: true, verbatim: true, dashes: true, verify: true, redone: 0, dropped: 0, kbWords: 0, itemN: m.mcqs.length },
  };
  const probs = LP.checkLesson(lesson);
  if (probs.length) { console.error("LESSON FAIL", m.id, JSON.stringify(probs)); failures++; continue; }
  fs.writeFileSync(path.join(LESSON_DIR, m.id + ".json"), JSON.stringify(lesson, null, 2) + "\n");
  written++;
  const kbPath = path.join(KB_DIR, m.kb + ".json");
  if (!fs.existsSync(kbPath)) {
    fs.writeFileSync(kbPath, JSON.stringify({ id: m.kb, name: m.kbName, aliases: [...m.aliases], class: "non_infective", system: "Pharmacology", specialty: "Pharmacology", referenceOnly: true, review: { status: "ai_drafted" }, reference: { source: REF, sourceEdition: "8th edition topic map (2026-10-13)", pages: null, clinicalPearls: [...m.pearls], pathophysiology: m.patho, additionalDifferentials: [...m.diffs], additionalInvestigations: [...m.invs] } }, null, 2) + "\n");
    kbWritten++;
  } else kbSkipped++;
  const items = m.mcqs.map((q) => ({ ...ITEM_META, ...q, topic: m.id }));
  fs.writeFileSync(path.join(SUBJECT_DIR, m.id + ".json"), JSON.stringify({ topic: m.id, set: "maikbook2", v: 1, items }, null, 2) + "\n");
}
let idx = JSON.parse(fs.readFileSync(path.join(LESSON_DIR, "index.json"), "utf8"));
for (const m of M) idx.modules[m.id] = { title: m.title, minutes: 6, steps: m.steps.length, gen: "AI" };
fs.writeFileSync(path.join(LESSON_DIR, "index.json"), JSON.stringify(idx, null, 2) + "\n");
let counts = JSON.parse(fs.readFileSync(path.join(ROOT, "prep/bank/overlay-counts.json"), "utf8"));
counts.sets.maikbook2.pharmacology = counts.sets.maikbook2.pharmacology || {};
for (const m of M) counts.sets.maikbook2.pharmacology[m.id] = m.mcqs.length;
fs.writeFileSync(path.join(ROOT, "prep/bank/overlay-counts.json"), JSON.stringify(counts, null, 2) + "\n");
let tc = fs.readFileSync(path.join(ROOT, "test/prep-books-mcqs.test.mjs"), "utf8");
const OLD_LINE = 'assert.equal(totalItems, 1180, "Expected 1180 high-yield verified MCQs in maikbook2 (160 OBG + 360 pathology batch 2 + 120 pharmacology batch 2 + 270 ENT + 170 psychiatry + 100 ophthalmology)");';
const NEW_LINE = 'assert.equal(totalItems, 1260, "Expected 1260 high-yield verified MCQs in maikbook2 (160 OBG + 360 pathology batch 2 + 200 pharmacology batch 2 + 270 ENT + 170 psychiatry + 100 ophthalmology)");';
tc = tc.split(OLD_LINE).join(NEW_LINE);
fs.writeFileSync(path.join(ROOT, "test/prep-books-mcqs.test.mjs"), tc);
console.log("modules:", M.length, "mcqs:", M.reduce((n, m) => n + m.mcqs.length, 0), "kbSkipped:", kbSkipped, " lesson failures:", failures);

